css:
/* SmartLearn Native Color Classes */
.sl-text-primary { color: var(--smartlearn-primary) !important; }
.sl-text-emphasis { color: var(--smartlearn-text) !important; }
.sl-text-muted { color: var(--smartlearn-text-muted) !important; }
.sl-bg-main { background-color: var(--smartlearn-bg) !important; }
.sl-bg-card { background-color: var(--smartlearn-card-bg) !important; border: 1px solid var(--smartlearn-card-border) !important; }
.sl-bg-primary { background-color: var(--smartlearn-primary) !important; }
.sl-cta-course .sl-btn-primary { background-color: var(--smartlearn-primary) !important; border-color: var(--smartlearn-primary) !important; color: #fff !important; transition: transform 0.3s ease, box-shadow 0.3s ease; }
.sl-cta-course .sl-btn-primary:hover { transform: translateY(-3px); box-shadow: 0 10px 20px rgba(0,0,0,0.2) !important; filter: brightness(0.9); }

.sl-cta-course .sl-meta-item { display: inline-flex; align-items: center; }
.sl-cta-course .sl-meta-item:not(:last-child)::after { content: "•"; margin-left: 0.75rem; opacity: 0.3; }
@media (max-width: 767.98px) {
    .sl-cta-course .border-start-md { border-left: none !important; }
    .sl-cta-course .sl-course-action { width: 100%; border-top: 1px solid var(--smartlearn-card-border); padding-top: 1.5rem; }
    .sl-cta-course .sl-meta-item:not(:last-child)::after { display: none; }
    .sl-cta-course .sl-meta-item { border: 1px solid var(--smartlearn-card-border); padding: 2px 8px; border-radius: 4px; }
}
